package co.kr.badara.dolswevoice;
import java.util.*;import org.json.*;
public final class LockTests {
 static int checks;static void ok(boolean x){checks++;if(!x)throw new AssertionError("Lock check "+checks);}interface Task{void run()throws Exception;}static void fails(Task t)throws Exception{boolean fail=false;try{t.run();}catch(Exception e){fail=true;}ok(fail);}
 static class Fixture implements HaClient.Transport {boolean allowed=true,group=false,offline=false;String state="locked",format="";int posts;String path="";JSONObject payload;public String request(String method,String path,JSONObject body)throws Exception{if(path.equals("/api/template")){if(offline)throw new java.io.IOException("offline");return allowed?"[\"lock.front\"]":"[]";}JSONObject attributes=new JSONObject().put("friendly_name","현관 도어록");if(!format.isEmpty())attributes.put("code_format",format);if(group)attributes.put("entity_id",new JSONArray().put("lock.other"));JSONObject entity=new JSONObject().put("entity_id","lock.front").put("state",state).put("attributes",attributes);if(path.equals("/api/states"))return new JSONArray().put(entity).put(new JSONObject().put("entity_id","lock.hidden").put("state","locked")).toString();if(path.startsWith("/api/states/"))return entity.toString();if(path.startsWith("/api/services/")){posts++;this.path=path;payload=body;return "[]";}throw new java.io.IOException("unexpected request");}}
 public static void main(String[] args)throws Exception{
 List<CommandRouter.Target> targets=Arrays.asList(new CommandRouter.Target("lock.front","현관문"),new CommandRouter.Target("light.hall","복도 등"));
 for(String command:Arrays.asList("현관문 잠가줘","현관문을 잠가주세요","현관문 잠궈줘","현관문 잠금 설정해줘"))ok(CommandRouter.plan(command,targets).service.equals("lock"));
 for(String command:Arrays.asList("현관문 잠금 해제해줘","현관문 열어줘","현관문 잠금 풀어줘","현관문 풀어주세요"))ok(CommandRouter.plan(command,targets).service.equals("unlock"));
 for(String command:Arrays.asList("현관문 상태 알려줘","현관문 잠겼어?","현관문 잠겨있어?","현관문 잠금 상태 알려줘"))ok(CommandRouter.plan(command,targets).query());
 for(String command:Arrays.asList("현관문 잠그지마","현관문 열지마","현관문 잠금 해제하지마","현관문 잠가줘 열어줘","현관문 켜줘","현관문 닫아줘","현관문 50퍼센트로 맞춰줘","현관문 열어줘 복도 등 켜줘","모든 문 열어줘"))fails(()->CommandRouter.plan(command,targets));
 Fixture f=new Fixture();HaClient client=new HaClient(f);ok(client.list("voicecall").size()==1&&client.list("voicecall").get(0).id.equals("lock.front"));CommandRouter.Plan lock=CommandRouter.plan("현관문 잠가줘",targets),unlock=CommandRouter.plan("현관문 잠금 해제해줘",targets),query=CommandRouter.plan("현관문 상태 알려줘",targets);
 for(String[] state:new String[][]{{"locked","잠김"},{"unlocked","잠금 해제"},{"locking","잠그는 중"},{"unlocking","잠금 해제 중"},{"jammed","잠금장치 걸림"}}){f.state=state[0];ok(client.execute("voicecall",query,false).contains(state[1]));}ok(f.posts==0);f.state="locked";
 fails(()->client.execute("voicecall",unlock,false));ok(f.posts==0);client.execute("voicecall",unlock,true);ok(f.posts==0);client.execute("voicecall",lock,false);ok(f.posts==1&&f.path.equals("/api/services/lock/lock")&&f.payload.getString("entity_id").equals("lock.front"));client.execute("voicecall",unlock,false,()->true,true,"");ok(f.posts==2&&f.path.equals("/api/services/lock/unlock"));
 f.format="^\\d{4}$";String response=client.execute("voicecall",unlock,false,()->true,true,"0123");ok(f.payload.getString("code").equals("0123")&&!response.contains("0123")&&!unlock.data.containsKey("code"));int before=f.posts;fails(()->client.execute("voicecall",unlock,false,()->true,true,"bad"));ok(f.posts==before);fails(()->client.execute("voicecall",unlock,false,()->false,true,"0123"));ok(f.posts==before);f.allowed=false;fails(()->client.execute("voicecall",unlock,false,()->true,true,"0123"));ok(f.posts==before);f.allowed=true;f.group=true;ok(client.list("voicecall").isEmpty());fails(()->client.execute("voicecall",unlock,false,()->true,true,"0123"));ok(f.posts==before);f.group=false;f.offline=true;fails(()->client.execute("voicecall",unlock,false,()->true,true,"0123"));ok(f.posts==before);f.offline=false;f.state="unavailable";fails(()->client.execute("voicecall",lock,false));ok(f.posts==before);
 fails(()->client.execute("voicecall",new CommandRouter.Plan(targets.get(0),"open"),false,()->true,true,"0123"));ok(f.posts==before);
 System.out.println(checks+" lock checks passed: discovery, Korean commands, unlock opt-in, state labels, optional code, label/home gating, no group or latch-open action.");
 }
}
